  // Fixed-width integer fields (ir/contract-check.ts): every class of the family stores the field as i32 (packed for
  // 8- and 16-bit types). Int32 fields come from int32Fields, the narrower and unsigned ones from narrowFields.
  {
    const families = new Map<string, NarrowKind>();
    for (const f of mod.contracts?.int32Fields ?? []) families.set(f, "Int32");
    for (const f of mod.contracts?.narrowFields ?? []) { const cut = f.lastIndexOf("\0"); families.set(f.slice(0, cut), f.slice(cut + 1) as NarrowKind); }
    if (families.size) {
      const byName = new Map((mod.classes ?? []).map(c => [c.name, c]));
      const out = new Map<string, NarrowKind>();
      for (const c of mod.classes ?? []) for (const f of c.fields) {
        if (f.type.kind !== "f64") continue;
        let top: string | null = null;
        for (let k = byName.get(c.name); k; k = k.base ? byName.get(k.base) : undefined) if (k.fields.some(x => x.name === f.name)) top = k.name;
        const kind = top !== null ? families.get(`${top}\0${f.name}`) : undefined;
        if (kind) out.set(`c:${c.name}.${f.name}`, kind);
      }
      types.narrowFields = out;
    }
  }
  const symbol = (name: string) => name.replace(/[^A-Za-z0-9_.$]/g, c => `_${c.charCodeAt(0).toString(16)}`);
  /** Property names inside helper names: injective (every character outside
   * [A-Za-z0-9$], "_" and "." included, becomes `_<hex>_`), because helpers
   * dedupe by name — `symbol` maps "é" and "_e9" to the same text. */
  const keySymbol = (name: string) => name.replace(/[^A-Za-z0-9$]/g, c => `_${c.charCodeAt(0).toString(16)}_`);
  let labelSeq = 0;
  let fn!: FnState;
  /* Source map (WasmGcEmitOptions.sourceMap): statement and call expressions note the location they lower from in their function's
   * `srcLocs`; once the function is added (Binaryen's debug locations are keyed by the function), attachLocs hands them over as
   * (file, line, column) with lines counted from 1 and columns from 0 in UTF-16 units, which is what TypeScript's positions are. */
  const SM = opts.sourceMap ?? null;
  const smFiles = new Map<string, { index: number; starts: number[] } | null>();
  const smFile = (file: string): { index: number; starts: number[] } | null => {
    let known = smFiles.get(file);
    if (known !== undefined) return known;
    const text = SM!.sourceText(file);
    if (text === undefined) known = null;
    else {
      const starts = [0];
      for (let i = 0; i < text.length; i++) {
        const c = text.charCodeAt(i);
        if (c === 10) starts.push(i + 1);
        else if (c === 13) { if (text.charCodeAt(i + 1) === 10) i++; starts.push(i + 1); }
        else if (c === 0x2028 || c === 0x2029) starts.push(i + 1);
      }
      known = { index: m.addDebugInfoFileName(file), starts };
    }
    smFiles.set(file, known);
    return known;
  };
  const noteLoc = (e: number, loc: SrcLoc | undefined): void => { if (loc?.file) (fn.srcLocs ??= []).push([e, loc]); };
  const attachLocs = (name: string): void => {
    const locs = fn.srcLocs;
    if (!SM || !locs) return;
    const func = m.getFunction(name);
    for (const [e, loc] of locs) {
      const file = smFile(loc.file);
      if (!file) continue;
      let lo = 0, hi = file.starts.length - 1;
      while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (file.starts[mid]! <= loc.start) lo = mid; else hi = mid - 1; }
      m.setDebugLocation(func, e, file.index, lo + 1, loc.start - file.starts[lo]!);
    }
  };
  let smMap: string | undefined;

  /* ── reachability ──────────────────────────────────────────────────── */
  const reachable = new Set<string>();
  const closureTargets = new Map<string, IrType & { kind: "func" }>();
  /** Closure types whose code may read THIS_N: closures of functions that
   * read `this`, and page functions wrapped as closures ($jsfn). A direct
   * callback loop over any other closure type need not set THIS_N. */
  const thisReadingClosures = new Set<string>(), builtWithoutThis = new Set<string>();
  const descendants = (name: string): string[] => [name, ...(types.subclasses.get(name) ?? []).flatMap(descendants)];
  // A worklist, not recursion: a call chain as deep as the whole engine's would
  // otherwise nest a JSON.stringify per edge and overflow the stack.
  const pending: string[] = [];
  let draining = false;
  // Rapid type analysis (closed world): an instance method of a class is reachable only when that class or a subclass is CONSTRUCTED in
  // reachable code (its constructor is reachable: `new`, a class value, a subclass's super call). Until then its calls are deferred; a
  // method whose class is never constructed has no receiver to run on, so its body is not scanned or emitted (a trap stub keeps the
  // symbol). Off under a shared runtime (dyn values, so class instances, cross between separately compiled modules; plain link exports and imports carry
  // only scalars) and in the all-functions probe mode.
  let scanning = "";
  const rtaOn = !opts.link?.sharedRuntime && !process.env["WASMGC_ALL_FUNCTIONS"] && process.env["SCRIPTC_WASMGC_NO_RTA"] !== "1";
  const rtaMethodOwner = new Map<string, string>(), rtaCtorOwner = new Map<string, string>();
  const rtaLive = new Set<string>(), rtaDeferred = new Map<string, string[]>();
  const classByName = new Map((mod.classes ?? []).map(c => [c.name, c]));
  // Pure module-level initialisers (what a bundler's unused-export elimination does, exactly): `const X = <pure expression>` at module level
  // whose binding no reachable code reads skips its initialiser. Pure: literals, record/array literals, closures without captures, union
  // wraps and reads of other non-TDZ immutable globals; nothing else (a call, a getter-bearing literal, a TDZ read) is pure. The statement stays
